```
@staticmethod
def _is_screen_within_constraints(screen_string: str, screen_options: Screen) -> bool:
    """
    Checks if the given screen dimensions are within the specified constraints.
    """
    try:
        screen = orjson.loads(screen_string[len('*STRINGIFIED*'):])
        return (
            (screen.get('width', 0) >= (int(screen_options.min_width) if screen_options.min_width else 0)
            and screen.get('width', 0) <= (int(screen_options.max_width) if screen_options.max_width else 1e5)
            and screen.get('height', 0) >= (int(screen_options.min_height) if screen_options.min_height else 0)
            and screen.get('height', 0) <= (int(screen_options.max_height) if screen_options.max_height else 1e5))
        )
    except (ValueError, TypeError):
        return False
```

